entries.content:
json
{
  "name": "龙文县中等职业技术学校",
  "parent_realm": "龙文县",
  "summary": "位于县城边缘，为无法升入高中的学生提供职业技能培训。这里管理松散，学生成分复杂，充满了江湖气。与其说是学校，更像是踏入社会前的缓冲地带。校园暴力、早恋和与校外人员的联系是常态，但也充满了直接的生存智慧与活力。",
  "figures": [
    {
      "name": "孙大海",
      "summary": "汽修专业的资深教师。一个体态微胖、善于变通的中年男人，在县城里人脉很广。他关心学生的就业出路胜过课堂纪律，有时会介绍学生去做一些“社会上的活儿”。"
    },
    {
      "name": "王莉",
      "summary": "秦月夕的闺蜜（但不知道秦月夕的千金身份），你另一个邻居王阿姨的女儿，就读于美容美发专业。她性格泼辣，为人仗义，打扮成熟，对县城里的一切门清。是你在职校学生群体中的重要信息来源。"
    }
  ],
  "locations": [
    {
      "name": "实训车间",
      "summary": "包括汽修、烹饪、美容美发等多个专业的实践场地。这里总是充斥着机器的轰鸣和化学品的气味，是学生们学习手艺的地方，也是拉帮结派、解决矛盾的非正式场所。"
    },
    {
      "name": "校企合作办公室",
      "summary": "负责安排学生实习和就业的部门。办公室的墙上挂满了与各类工厂、饭店、发廊的合作锦旗，每一面锦旗背后都可能是一批学生的未来去向。"
    },
    {
      "name": "阿洪烧烤摊",
      "summary": "紧邻学校后墙的露天摊位，由一对中年夫妇经营。入夜后，这里就成了职校学生们的露天食堂和社交中心，混杂着烟酒气和各种真假难辨的传闻。"
    }
  ]
}

