  "name": "龙山公园",
  "parent_realm": "龙文县",
  "summary": "位于县城东侧的自然公园，紧邻县政府大楼。是县城内唯一的公共绿地。山路蜿蜒，树木葱郁，是居民们散步、锻炼和情侣约会的地方。因其僻静和多样的地形，这里也成为一些秘密会面和私人交易的天然场所。",
  "figures": [
    {
      "name": "老廖",
      "summary": "公园看门人兼护林员。一个沉默寡言的老人，每天在山上巡视。他对公园的每一条小路、每一个角落都了如指掌，也对在这里发生的各种事情心如明镜，但从不多言。"
    }
  ],
  "locations": [
    {
      "name": "望乡亭",
      "summary": "位于龙山山顶的一座凉亭。在这里可以俯瞰整个龙文县城的全貌。是学生们逃课、情侣谈心以及个人独处思考的绝佳地点。"
    },
    {
      "name": "龙涎湖",
      "summary": "山脚下的一个小人工湖，湖水并不清澈。湖边有几条供出租的旧脚踏船。黄昏时分，这里是情侣们最喜欢的去处。"
    },
    {
      "name": "龙文县综合行政中心",
      "summary": "一座现代化的办公大楼，突兀的楼高和崭新的外饰与整个陈旧的县城格格不入。是全县最高、设施最完备的建筑，也是龙文县县委、县政府的办公场所。"
    }
  ]
}

